function tokenize(cmd){
  cmd=String(cmd||'').replace(/\\\r?\n/g,' ').trim();
  var out=[],cur='',q=null;
  for(var i=0;i<cmd.length;i++){
    var c=cmd[i];
    if(q){ if(c===q) q=null; else cur+=c; }
    else if(c==='"'||c==="'") q=c;
    else if(/\s/.test(c)){ if(cur){ out.push(cur); cur=''; } }
    else cur+=c;
  }
  if(cur) out.push(cur);
  return out;
}
var FLAG_ARG={'-p':1,'--publish':1,'-v':1,'--volume':1,'-e':1,'--env':1,'--name':1,'--restart':1,'--network':1,'--net':1,'--hostname':1,'-h':1,'--user':1,'-u':1,'-w':1,'--workdir':1,'--entrypoint':1,'--label':1,'-l':1,'--add-host':1,'--dns':1,'--env-file':1,'--memory':1,'-m':1,'--cpus':1,'--device':1,'--cap-add':1,'--cap-drop':1,'--health-cmd':1,'--log-driver':1,'--platform':1,'--pull':1,'--shm-size':1,'--expose':1};
var FLAG_BOOL={'-d':1,'--detach':1,'-i':1,'--interactive':1,'-t':1,'--tty':1,'--rm':1,'--privileged':1,'--init':1,'--read-only':1,'--no-healthcheck':1,'-P':1,'--publish-all':1};
function parseDockerRun(cmd){
  var t=tokenize(cmd);
  if(t[0]==='docker') t.shift();
  if(t[0]==='container') t.shift();
  if(t[0]==='run'||t[0]==='create') t.shift();
  var o={image:null,command:[],name:null,ports:[],volumes:[],env:[],restart:null,networks:[],hostname:null,user:null,workdir:null,entrypoint:null,labels:[],extraHosts:[],dns:[],envFiles:[],devices:[],capAdd:[],capDrop:[],privileged:false,readOnly:false,init:false,tty:false,stdinOpen:false,memory:null,cpus:null,platform:null,shmSize:null,expose:[],unknown:[]};
  var i=0;
  while(i<t.length){
    var a=t[i];
    if(o.image){ o.command.push(a); i++; continue; }
    if(a[0]!=='-'){ o.image=a; i++; continue; }
    var key=a,val=null,eq=a.indexOf('=');
    if(a.slice(0,2)==='--'&&eq>0){ key=a.slice(0,eq); val=a.slice(eq+1); }
    if(FLAG_BOOL[key]){
      if(key==='-d'||key==='--detach'){} 
      else if(key==='--rm'){}
      else if(key==='--privileged') o.privileged=true;
      else if(key==='--read-only') o.readOnly=true;
      else if(key==='--init') o.init=true;
      else if(key==='-t'||key==='--tty') o.tty=true;
      else if(key==='-i'||key==='--interactive') o.stdinOpen=true;
      i++; continue;
    }
    if(FLAG_ARG[key]){
      if(val===null){ val=t[i+1]; i+=2; } else i++;
      if(val===undefined){ o.unknown.push(key); break; }
      if(key==='-p'||key==='--publish') o.ports.push(val);
      else if(key==='-v'||key==='--volume') o.volumes.push(val);
      else if(key==='-e'||key==='--env') o.env.push(val);
      else if(key==='--name') o.name=val;
      else if(key==='--restart') o.restart=val;
      else if(key==='--network'||key==='--net') o.networks.push(val);
      else if(key==='--hostname'||key==='-h') o.hostname=val;
      else if(key==='--user'||key==='-u') o.user=val;
      else if(key==='-w'||key==='--workdir') o.workdir=val;
      else if(key==='--entrypoint') o.entrypoint=val;
      else if(key==='--label'||key==='-l') o.labels.push(val);
      else if(key==='--add-host') o.extraHosts.push(val);
      else if(key==='--dns') o.dns.push(val);
      else if(key==='--env-file') o.envFiles.push(val);
      else if(key==='--memory'||key==='-m') o.memory=val;
      else if(key==='--cpus') o.cpus=val;
      else if(key==='--device') o.devices.push(val);
      else if(key==='--cap-add') o.capAdd.push(val);
      else if(key==='--cap-drop') o.capDrop.push(val);
      else if(key==='--platform') o.platform=val;
      else if(key==='--shm-size') o.shmSize=val;
      else if(key==='--expose') o.expose.push(val);
      continue;
    }
    o.unknown.push(a); i++;
  }
  if(!o.image) throw new Error('未找到镜像名，请检查命令');
  return o;
}
function yq(s){
  s=String(s);
  if(/^[A-Za-z0-9._\/:@-]+$/.test(s)) return s;
  return '"'+s.replace(/\\/g,'\\\\').replace(/"/g,'\\"')+'"';
}
function yqq(s){
  s=String(s);
  return '"'+s.replace(/\\/g,'\\\\').replace(/"/g,'\\"')+'"';
}
function toCompose(cmd){
  var o=parseDockerRun(cmd);
  var svc=o.name||String(o.image).split(':')[0].split('/').pop().replace(/[^A-Za-z0-9_-]/g,'')||'app';
  var L=[];
  L.push('services:');
  L.push('  '+svc+':');
  L.push('    image: '+yq(o.image));
  if(o.name) L.push('    container_name: '+yq(o.name));
  if(o.platform) L.push('    platform: '+yq(o.platform));
  if(o.hostname) L.push('    hostname: '+yq(o.hostname));
  if(o.user) L.push('    user: '+yq(o.user));
  if(o.workdir) L.push('    working_dir: '+yq(o.workdir));
  if(o.entrypoint) L.push('    entrypoint: '+yq(o.entrypoint));
  if(o.restart) L.push('    restart: '+yq(o.restart));
  if(o.privileged) L.push('    privileged: true');
  if(o.readOnly) L.push('    read_only: true');
  if(o.init) L.push('    init: true');
  if(o.tty) L.push('    tty: true');
  if(o.stdinOpen) L.push('    stdin_open: true');
  if(o.memory) L.push('    mem_limit: '+yq(o.memory));
  if(o.cpus) L.push('    cpus: '+yq(o.cpus));
  if(o.shmSize) L.push('    shm_size: '+yq(o.shmSize));
  function list(kk,arr,force){ if(arr.length){ L.push('    '+kk+':'); arr.forEach(function(v){ L.push('      - '+(force?yqq(v):yq(v))); }); } }
  list('ports',o.ports,true);
  list('expose',o.expose);
  list('volumes',o.volumes);
  list('environment',o.env);
  list('env_file',o.envFiles);
  list('labels',o.labels);
  list('extra_hosts',o.extraHosts);
  list('dns',o.dns);
  list('devices',o.devices);
  list('cap_add',o.capAdd);
  list('cap_drop',o.capDrop);
  if(o.networks.length){
    list('networks',o.networks);
  }
  if(o.command.length) L.push('    command: '+yq(o.command.join(' ')));
  if(o.networks.length){
    L.push('networks:');
    o.networks.forEach(function(n){ L.push('  '+n+':'); L.push('    external: true'); });
  }
  var warn=o.unknown.length?('# 警告: 未识别参数 '+o.unknown.join(' ')+'\n'):'';
  return warn+L.join('\n')+'\n';
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { tokenize:tokenize, parseDockerRun:parseDockerRun, toCompose:toCompose };
}
if (typeof window !== 'undefined') {
  window.DockerForgePure = { tokenize:tokenize, parseDockerRun:parseDockerRun, toCompose:toCompose };
}
